items=[]
for sprint,(title,goal,rows) in enumerate(SPRINTS,1):
    for row in rows.strip().splitlines():
        title_item,points,deps,source,criteria=row.split('|')
        ident=f'KB-{len(items)+1:03d}'
        items.append(dict(id=ident,title=title_item,sprint=sprint,points=int(points),dependencies=deps.split(',') if deps else [],source=source,criteria=criteria.split('; '),priority='high' if sprint<=2 or any(x in title_item.lower() for x in ['paiement','conflit','sécurité','restauration']) else 'normal'))

EPICS = ['Cadrage et socle', 'Identité et accès', 'Catalogue et validation', 'Découverte et contact', 'Réservation', 'Suivi RDV et communication', 'Souscription et paiement', 'Cycle financier', 'Administration métier', 'Qualité et plateformes', 'Lancement', 'Exploitation et amélioration']
for t in items:
    t['epic']=EPICS[t['sprint']-1]
    t['type']='Livraison conditionnelle' if 'Condition plateforme' in t['source'] else ('Exigence CDC' if t['source'].startswith('CDC') else 'Complément de réalisation')
    t['rank']=int(t['id'].split('-')[1])

def description(t):
    return f"## Objectif\n{t['title']}\n\n## Traçabilité\nRéférence : {t['source']}\nIdentifiant : {t['id']}\nEpic : {t['epic']}\nNature : {t['type']}\nOrdre initial : {t['rank']} (à arbitrer par le Product Owner)\nSprint prévisionnel : {t['sprint']:02d}\nEstimation indicative : {t['points']} points, à réestimer par l’équipe (pas une durée).\nDépendances : {', '.join(t['dependencies']) or 'Aucune'}\n\n## Critères d’acceptation\n"+'\n'.join('- [ ] '+c for c in t['criteria'])+"\n\n## Réalisation\n- [ ] Affiner la règle et les cas limites avec le Product Owner.\n- [ ] Réaliser les changements et la documentation nécessaires.\n- [ ] Vérifier les critères ci-dessus et joindre les preuves.\n- [ ] Revue et intégration en recette selon la Definition of Done.\n\nLes sous-tâches techniques et affectations seront détaillées par les Developers pendant le Sprint Planning."

for t in items:t['description']=description(t)
ids={x['id']:x for x in items}
assert len(ids)==84
for t in items:
    for d in t['dependencies']:
        assert d in ids and ids[d]['sprint']<=t['sprint'] and d<t['id'], (t['id'],d)
data={'version':'1.0-proposition','sprint_duration_weeks':2,'calendar_confirmed':False,'sprints':[{'number':i,'title':s[0],'goal':s[1],'points':sum(t['points'] for t in items if t['sprint']==i)} for i,s in enumerate(SPRINTS,1)],'items':items}
(ROOT/'backlog.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
md=['# Keke Beauty — Product Backlog et trajectoire Scrum','', 'Proposition initiale issue de CDC_Keke Beauty (sections 1 à 5). Les compléments nécessaires à la qualité, au lancement et à l’exploitation sont identifiés. Aucun développement n’est déclaré terminé.', '', '## Objectif produit', '', 'Permettre aux clients de trouver un établissement de beauté fiable, le contacter et réserver ; permettre aux partenaires vérifiés de gérer leur activité et leur abonnement ; permettre à Keke Beauty de contrôler et exploiter le service.', '', '## Hypothèses de planification', '', '- 12 sprints de 2 semaines = trajectoire nominale de 24 semaines, pas un engagement de délai.', '- Équipe, disponibilité, date de départ et vélocité inconnues : aucune affectation ni échéance calendaire inventée.', '- Les points sont des estimations initiales de complexité, à reprendre en équipe. Ils ne se convertissent pas directement en jours.', '- Les sprints futurs sont une prévision. Le Sprint Backlog effectif est sélectionné avec les Developers au Sprint Planning selon capacité et dépendances.', '- Les travaux web/Android/iOS sont conditionnels au choix du Sprint 1. Les charges de livraison finale ne couvrent pas à elles seules le développement de trois clients : chaque fonctionnalité antérieure doit être réestimée pour toutes les plateformes retenues.', '- Les tâches anomalies/incidents sont des enveloppes prévisionnelles à remplacer par les défauts réellement observés et à réestimer.', '- Les paiements concernent les abonnements des établissements. Le paiement des soins, les commissions, avis clients, messagerie et fidélité ne sont pas exigés dans le CDC et ne sont pas ajoutés au périmètre.', '', '## Organisation Scrum', '', '- Product Owner : une personne responsable des priorités, décisions produit et critères d’acceptation, à nommer.', '- Scrum Master : accompagne la méthode, les événements et la levée des obstacles, à nommer.', '- Developers : équipe pluridisciplinaire assurant conception, réalisation, tests et exploitation ; affectations décidées collectivement.', '- Cadence proposée : Planning 2 h au début, Daily 15 min les jours ouvrés, Review 1 h et Rétrospective 1 h en fin de sprint ; affinement 1 h par semaine. Ajuster les durées aux besoins.', '- Chaque Review démontre un incrément utilisable et adapte les priorités. Chaque Rétrospective retient au moins une amélioration suivie au sprint suivant.', '- Aucun Sprint 0 imposé : le premier sprint inclut une fiche utilisable en recette, en plus du cadrage.', '', '## Definition of Ready — accord de travail proposé', '', 'Objectif compris, critères vérifiables, dépendances identifiées, décisions bloquantes résolues, exemples et maquette disponibles si nécessaires, taille compatible avec le sprint. Cette checklist est un accord local et non une règle imposée par Scrum.', '', '## Definition of Done — à adopter par l’équipe', '', '- Critères d’acceptation vérifiés et preuves jointes ; cas d’erreur et droits d’accès couverts.', '- Revue effectuée ; contrôles automatisés adaptés au risque réussis ; absence d’anomalie critique ou bloquante connue.', '- Intégration en recette, documentation et migrations à jour ; secrets et données sensibles protégés.', '- Accessibilité, compatibilité et performance vérifiées selon les seuils convenus pour le changement.', '- Incrément démontrable ; données de test identifiables. Une revue produit ne remplace pas les contrôles qualité.', '', '## Gestion ClickUp proposée', '', '- Dossier : Keke Beauty — Scrum, dans Espace de l’équipe.', '- Product Backlog : source unique des éléments KB-001 à KB-084.', '- Une liste par sprint : objectif, prévision, critères de sortie et références aux mêmes tâches. Si Tasks in Multiple Lists est disponible, rattacher les tâches existantes sans les dupliquer ; sinon conserver les tâches dans Product Backlog et utiliser des liens dans les fiches sprint.', '- Une fiche de pilotage par sprint : Planning, Daily, affinement, Review, Rétrospective et suivi de l’objectif.', '- Champs proposés : ID CDC, type/epic, priorité, points, sprint prévisionnel, responsable, dépendances. En l’absence de champs configurables, les descriptions restent la référence.', '- Workflow proposé à adapter aux statuts réellement disponibles : À affiner → Prêt → En cours → En revue → En test → Terminé ; blocages signalés avec cause et responsable.', '- Limiter le travail en cours selon la capacité ; mesurer points terminés, objectif atteint, défauts et éléments bloqués. Ne pas compter les points des fiches de pilotage.', '- Ne pas cloner les stories dans plusieurs sprints : déplacer la prévision des tâches inachevées et conserver leur historique.', '', '## Décisions et risques à traiter tôt', '', '| Sujet | Action / preuve attendue | Responsable fonctionnel | Échéance relative |', '|---|---|---|---|', '| Plateformes, pays, devise, équipe et budget | Décision KB-001 ; ajuster charges et calendrier | Product Owner | Sprint 1 |', '| Capacité des salons et règles RDV | Décision KB-002 avec exemples de chevauchement | Product Owner + partenaires pilotes | Sprint 1 |', '| Engagement annuel et impayés | Conditions, grâce, renouvellement et impact sur RDV | Product Owner | Avant Sprint 5, puis Sprint 7 |', '| SMS et paiement locaux | Accès sandbox, couverture réelle, quotas, coûts, contrats | Équipe technique + responsable métier | Sprint 1 ; production avant Sprint 11 |', '| Yango et applications de cartes | Preuve de lien sur appareils ; repli si indisponible | Developers | Sprint 1 puis Sprint 4 |', '| Données KYC et personnelles | Accès, conservation, suppression et règles pays | Responsable désigné par le Product Owner | Sprint 2 |', '| Stores mobiles | Comptes, signature et délais externes si mobile retenu | Responsable publication | Démarrer Sprint 1 ; prêt Sprint 10 |', '| Performance et reprise | Volumes, p95, disponibilité, RPO/RTO à convenir | Product Owner + Developers | Cadrage puis mesure Sprint 10 |', '', '## Trajectoire des sprints', '', '| Sprint | Objectif / résultat attendu | Points indicatifs |', '|---|---|---:|']
for s in data['sprints']:md.append(f"| {s['number']:02d} — {s['title']} | {s['goal']} | {s['points']} |")
md += ['',f"Total indicatif : {sum(t['points'] for t in items)} points pour {len(items)} éléments, avant réestimation des plateformes et de la capacité.", '', '## Jalons', '', '- Fin S4 : annuaire, fiches, recherche, appel et itinéraire démontrables.', '- Fin S6 : parcours RDV complet, notifications et concurrence testés.', '- Fin S8 : abonnement, encaissements et suivi financier démontrables.', '- Fin S9 : exploitation métier testée avec pilotes.', '- Fin S10 : qualité mesurée et plateformes retenues prêtes pour recette.', '- Fin S11 : lancement sous réserve de recette, accès production et éventuelles validations des stores.', '- Fin S12 : stabilisation, transfert et backlog de maintenance.', '', '## Couverture du cahier des charges', '', '| Exigence | Éléments |', '|---|---|', '| Application et cibles | KB-001, KB-006, KB-067 à KB-069 |', '| Violet/blanc, ergonomie, médias | KB-003, KB-018, KB-019, KB-025, KB-066 |', '| Téléphone et OTP | KB-008 à KB-010 |', '| Recherche et géolocalisation | KB-021 à KB-024 |', '| Prestations, tarifs, appel, itinéraire | KB-017, KB-020, KB-025 à KB-027 |', '| Calendrier, rouge indisponible, confirmations/refus | KB-029 à KB-042 |', '| Onboarding, identité, horaires, GPS | KB-011 à KB-016, KB-030 |', '| Abonnement annuel, facturation mensuelle/annuelle | KB-043, KB-044, KB-049, KB-051 à KB-053 |', '| Mobile Money, Visa, Mastercard | KB-045 à KB-048, KB-050, KB-054 |', '| API, cloud, disponibilité | KB-004, KB-005, KB-024, KB-027, KB-040, KB-065, KB-070 |', '| Back-office, KYC, finances et paramétrage | KB-015, KB-021, KB-043, KB-052, KB-055, KB-057 à KB-062 |', '', '## Backlog détaillé', '']
for s in data['sprints']:
    md += [f"## Sprint {s['number']:02d} — {s['title']}",'',s['goal'],'']
    for t in items:
        if t['sprint']!=s['number']:continue
        md += [f"### {t['id']} — {t['title']}",'',f"Priorité : {t['priority']} · Points : {t['points']} · Source : {t['source']}",f"Dépendances : {', '.join(t['dependencies']) or 'Aucune'}",'']+['- [ ] '+c for c in t['criteria']]+['']
md += ['## Référence méthodologique','','Scrum Guide officiel : https://scrumguides.org/scrum-guide.html. Les durées d’événements proposées, les points et la Definition of Ready sont des accords locaux, pas des prescriptions supplémentaires de Scrum.','']
(ROOT/'BACKLOG_SCRUM_KEKE_BEAUTY.md').write_text('\n'.join(md),encoding='utf-8')
print(json.dumps({'items':len(items),'sprints':len(SPRINTS),'points':sum(t['points'] for t in items),'dependencies':sum(len(t['dependencies']) for t in items)},ensure_ascii=False))
